export const REAL_LARK_LISTINGS_SYNC_VERSION = '2026-10-31-lark31-v5';

const normStoreKey = (v?: string) =>
  (v || '').trim().toLowerCase().replace(/[\s\-_]+/g, '');

let _byLowerBoardKey: Map<string, KocListingItem[]> | null = null;
let _byMonthAndStore: Map<string, KocListingItem[]> | null = null;

function ensureListingIndexes() {
  if (_byLowerBoardKey && _byMonthAndStore) return;
  _byLowerBoardKey = new Map<string, KocListingItem[]>();
  _byMonthAndStore = new Map<string, KocListingItem[]>();
  for (const [bKey, items] of Object.entries(REAL_LARK_LISTINGS_BY_BOARD_KEY)) {
    _byLowerBoardKey.set(bKey.toLowerCase(), items);
    if (Array.isArray(items) && items.length > 0) {
      const first = items[0];
      const month = (first.monthKey || '').trim();
      const sName = normStoreKey(first.storeName);
      const sId = normStoreKey(first.storeId);
      if (month && sName) {
        _byMonthAndStore.set(`${month}__${sName}`, items);
      }
      if (month && sId) {
        _byMonthAndStore.set(`${month}__${sId}`, items);
      }
    }
  }
}

export function getRealLarkListingsForBoardKey(
  boardKey: string,
  planMeta?: { month?: string; storeName?: string; storeId?: string }
): KocListingItem[] {
  ensureListingIndexes();
  const direct =
    REAL_LARK_LISTINGS_BY_BOARD_KEY[boardKey] ||
    _byLowerBoardKey?.get((boardKey || '').toLowerCase());
  if (direct && direct.length > 0) return direct;
  if (planMeta?.month) {
    const m = planMeta.month.trim();
    const byName = planMeta.storeName
      ? _byMonthAndStore?.get(`${m}__${normStoreKey(planMeta.storeName)}`)
      : undefined;
    if (byName && byName.length > 0) return byName;
    const byId = planMeta.storeId
      ? _byMonthAndStore?.get(`${m}__${normStoreKey(planMeta.storeId)}`)
      : undefined;
    if (byId && byId.length > 0) return byId;
  }
  return [];
}

